{"path": "/workspace/output/_work/extract.py", "content": "#!/usr/bin/env python3
"""Extract (phrase, clue-image) question items from the four picture-word-guessing decks."""
import json, os, re, zipfile, unicodedata
from lxml import etree

NS = {'a': 'http://schemas.openxmlformats.org/drawingml/2006/main',
      'p': 'http://schemas.openxmlformats.org/presentationml/2006/main',
      'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}
EMU = 914400.0

SOURCES = {
    '1.pptx': dict(headers=[],   # question ranges derived below from 'End of Set' markers
                   ranged=True),
    '2.pptx': dict(headers=[1, 2]),
    '3.pptx': dict(headers=[1, 2, 3]),
    '4.pptx': dict(headers=[1, 2]),
}

NOISE = re.compile(r'^(Question\s*\d+:?|Set\s+\d+|Game Rules|Game Rules:|Charades.*|'
                   r'Get Ready.*|Start the Timer.*|End of Set.*|'
                   r'Let\'s test how in sync we are!|XXX)$', re.I)
CJK = re.compile(r'[㐀-鿿豈-﫿]')


def is_noise(s):
    s = s.strip()
    if not s:
        return True
    if NOISE.match(s):
        return True
    if len(s) > 60:                       # rule-book paragraphs
        return True
    if any(k in s for k in ('audience members', 'Time limit', 'Form teams freely',
                            'guesser must', 'one acts and one guesses', 'Back to Home',
                            'During guessing', 'End of Set', 'may not look at the screen',
                            'Audience members', 'If a clue', 'The final winner')):
        return True
    return False


def phrase_texts(slide_el):
    out = []
    for sp in slide_el.iter('{%s}sp' % NS['p']):
        t = ''.join((x.text or '') for x in sp.iter('{%s}t' % NS['a']))
        t = unicodedata.normalize('NFKC', t)
        t = re.sub(r'\s+', ' ', t).strip()
        if not is_noise(t):
            out.append(t)
    return out


def slide_images(root, rels, sw, sh):
    """Return list of dicts describing every raster image placed on the slide."""
    res = []

    def add(target, off, ext, kind):
        if target is None:
            return
        x, y, w, h = off
        res.append(dict(target=target, x=x, y=y, w=w, h=h, area=w * h, kind=kind))

    # slide background
    bg = root.find('.//p:cSld/p:bg', NS)
    if bg is not None:
        blip = bg.find('.//a:blip', NS)
        if blip is not None:
            tgt = rels.get(blip.get('{%s}embed' % NS['r']))
            if tgt:
                add(tgt, (0, 0, sw, sh), bg='bg') if False else add(tgt, (0, 0, sw, sh), None, 'bg') if False else None
    # (simple, explicit helper below instead)

    def blip_of(el):
        b = el.find('.//a:blip', NS)
        if b is None:
            return None
        return rels.get(b.get('{%s}embed' % NS['r']))

    def geom(el):
        xfrm = None
        for path in ('./p:spPr/a:xfrm', './p:grpSpPr/a:xfrm', './p:blipFill/a:xfrm',
                     './p:xfrm'):
            xfrm = el.find(path, NS)
            if xfrm is not None:
                break
        if xfrm is None:
            xfrm = el.find('.//a:xfrm', NS)
        if xfrm is None:
            return None
        o = xfrm.find('a:off', NS)
        e = xfrm.find('a:ext', NS)
        if o is None or e is None:
            return None
        return (int(o.get('x')) / EMU, int(o.get('y')) / EMU,
                int(e.get('cx')) / EMU, int(e.get('cy')) / EMU)

    res = []
    if bg is not None:
        b = blip_of(bg)
        if b:
            res.append(dict(target=b, x=0, y=0, w=sw, h=sh, area=sw * sh, kind='bg'))

    def walk(node, tx=None):
        for el in node:
            tag = etree.QName(el).localname
            if tag == 'nvGrpSpPr':
                continue
            if tag == 'grpSp':
                g = geom(el)
                chOff = chExt = None
                xfrm = el.find('./p:grpSpPr/a:xfrm', NS)
                if xfrm is not None:
                    co = xfrm.find('a:chOff', NS)
                    ce = xfrm.find('a:chExt', NS)
                    if co is not None and ce is not None:
                        chOff = (int(co.get('x')) / EMU, int(co.get('y')) / EMU)
                        chExt = (int(ce.get('cx')) / EMU, int(ce.get('cy')) / EMU)
                new_tx = (g, chOff, chExt)
                walk(el, new_tx)
                continue
            if tag == 'pic':
                g, blip = None, None
                sp = el.find('./p:spPr/a:xfrm', NS)
                if sp is not None:
                    o = sp.find('a:off', NS); e = sp.find('a:ext', NS)
                    g = (int(o.get('x')) / EMU, int(o.get('y')) / EMU,
                         int(e.get('cx')) / EMU, int(e.get('cy')) / EMU)
                b = blip_of(el)
                if g and tx:
                    goff, chOff, chExt, = tx[0], tx[1], tx[2]
                    if chExt and chExt[0] and chExt[1]:
                        sx = goff[2] / chExt[0]; sy = goff[3] / chExt[1]
                        nx = goff[0] + (g[0] - chOff[0]) * sx
                        ny = goff[1] + (g[1] - chOff[1]) * sy
                        g = (nx, ny, g[2] * sx, g[3] * sy)
                if b and g:
                    res.append(dict(target=b, x=g[0], y=g[1], w=g[2], h=g[3],
                                    area=g[2] * g[3], kind='pic'))
                continue
            if tag == 'sp':
                g = geom(el)
                b = el.find('./p:spPr/a:blipFill/a:blip', NS)
                if b is not None and g:
