    sz = pres.find('.//p:sldSz', NS)
    sw, sh = int(sz.get('cx')) / EMU, int(sz.get('cy')) / EMU
    slides = []
    for i, sid in enumerate(order, 1):
        target = 'ppt/' + prels[sid].replace('../', '')
